n/// This model contains row level security and requires additional setup for migrations. Visit https://pris.ly/d/row-level-security for more info.\nmodel tasks {\n  id               Int                @id @default(autoincrement())\n  title            String             @db.VarChar(200)\n  description      String?\n  created_by       String             @db.VarChar(20)\n  deadline         DateTime           @db.Timestamptz(6)\n  created_at       DateTime           @default(now()) @db.Timestamptz(6)\n  task_assignments task_assignments[]\n  employees        employees          @relation(fields: [created_by], references: [emp_id], onDelete: Cascade)\n}\n\n/// This model contains row level security and requires additional setup for migrations. Visit https://pris.ly/d/row-level-security for more info.\nmodel transfer_budgets {\n  id            Int       @id @default(autoincrement())\n  emp_id        String    @unique @db.VarChar(20)\n  balance       Int       @default(20)\n  monthly_topup Int       @default(20)\n  updated_at    DateTime  @default(now()) @db.Timestamptz(6)\n  last_topup_at DateTime? @db.Timestamptz(6)\n  employees     employees @relation(fields: [emp_id], references: [emp_id], onDelete: Cascade)\n}\n\nmodel MarketingLead {\n  id                  String     @id @default(cuid())\n  customerName        String\n  phoneNumber         String?\n  productOfInterest   String?\n  productType         String?\n  conversationContent String?\n  createdByUserId     String\n  isForwarded         Boolean    @default(false)\n  forwardedAt         DateTime?\n  quotationId         String?    @unique\n  createdAt           DateTime   @default(now()) @db.Timestamptz(6)\n  updatedAt           DateTime   @default(now()) @updatedAt @db.Timestamptz(6)\n  assignedToId        String?\n  isContacted         Boolean    @default(false)\n  assignedTo          User?      @relation(\"AssignedLeads\", fields: [assignedToId], references: [id])\n  createdBy           User       @relation(fields: [createdByUserId], references: [id])\n  quotation           Quotation? @relation(fields: [quotationId], references: [id])\n}\n\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String\n  title     String\n  message   String\n  isRead    Boolean  @default(false)\n  linkUrl   String?\n  type      String\n  createdAt DateTime @default(now()) @db.Timestamptz(6)\n  user      User     @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([createdAt])\n  @@index([isRead])\n}\n\nmodel SiteSurvey {\n  id                        String                   @id @default(cuid())\n  surveyNumber              String                   @unique\n  surveyDate                DateTime                 @db.Date\n  companyId                 String?\n  customerName              String?\n  projectName               String?\n  projectLocation           String?\n  coordinatorName           String?\n  coordinatorPhone          String?\n  salespersonId             String\n  surveyorName              String?\n  status                    String                   @default(\"Draft\")\n  version                   Int                      @default(1)\n  latitude                  Float?\n  longitude                 Float?\n  hasSingleLineDiagram      Boolean                  @default(false)\n  requiredInfoChecklist     String[]                 @default([])\n  additionalRemark          String?\n  createdAt                 DateTime                 @default(now()) @db.Timestamptz(6)\n  updatedAt                 DateTime                 @updatedAt @db.Timestamptz(6)\n  estimatedAt               DateTime?\n  estimatedByUserId         String?\n  estimatedPrice            Float?\n  estimationNote            String?\n  estimationStatus          String?\n  amrCustomerCode           String?\n  buildingElectricalFileUrl String?\n  buildingPlanFileUrl       String?\n  electricalCabinetFileUrl  String?\n  loadProfileFileUrl        String?\n  roofStructureFileUrl      String?\n  quotations                Quotation[]\n  company                   Company?                 @relation(fields: [companyId], references: [id])\n  estimatedByUser           User?                    @relation(\"SurveyEstimator\", fields: [estimatedByUserId], references: [id])\n  salesperson               User                     @relation(fields: [salespersonId], references: [id])\n  electricityBill           SurveyBill?\n  documents                 SurveyDocument[]\n  electricalProfile         SurveyElectricalProfile?\n  photos                    SurveyPhoto[]\n  qa                        SurveyQA?\n  structure                 SurveyStructure?\n  tariffSelection           SurveyTariffSelection?\n  usageBehavior             SurveyUsageBehavior?\n}\n\nmodel SurveyUsageBehavior {\n  id                    String     @id @default(cuid())\n  surveyId              String     @unique\n  workingHours          String?\n  workingDaysPerWeek    Int?\n  workingDaysPerYear    Int?\n  nonWorkingDaysPerWeek Int?\n  nonWorkingDaysPerYear Int?\n  dayNightRatio         String?\n  avgBillThbPerMonth    Float?\n  mainEquipment         String?\n  survey                SiteSurvey @relation(fields: [surveyId], references: [id], onDelete: Cascade)\n}\n\nmodel SurveyElectricalProfile {\n  id                    String     @id @default(cuid())\n  surveyId              String     @unique\n  gridProvider          String?\n  userType              String?\n  voltageLevel          String[]   @default([])\n  meterSize             String[]   @default([])\n  rateThbPerKwh         Float?\n  kwhQty                Float?\n  peakKwWeekday         Float?\n  peakKwWeekend         Float?\n  transformerCount      Int?\n  transformerBrand      String?\n  transformerModel      String?\n  transformerKva        Float?\n  breakerAmp            Float?\n  mainPanelCableLengthM Float?\n  amrUsernameEncrypted  String?\n  amrPasswordEncrypted  String?\n  survey                SiteSurvey @relation(fields: